/**
 * UI-004 measurement driver.
 *
 * Serves the production build (vite preview) and drives it with a real
 * Chromium-family browser via puppeteer-core — Edge by default, which shares
 * the engine WebView2 uses, so numbers approximate the Tauri target.
 *
 *   node scripts/measure.mjs [--quick] [--browser=edge|chrome] [--url=http://localhost:4173]
 *
 * Writes measurements/ui-004-<timestamp>.json (gitignored) and prints the
 * same JSON to stdout.
 */
import { existsSync, mkdirSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { spawn } from 'node:child_process'
import puppeteer from 'puppeteer-core'

const here = dirname(fileURLToPath(import.meta.url))
const appDir = join(here, '..')
const outDir = join(appDir, 'measurements')

const args = process.argv.slice(2)
const quick = args.includes('--quick')
// Edge headless conflicts with an existing Edge session on some machines;
// Chrome is the default (same Chromium engine family as WebView2).
const browserArg = args.find((a) => a.startsWith('--browser='))?.split('=')[1] ?? 'chrome'
const explicitUrl = args.find((a) => a.startsWith('--url='))?.split('=')[1]
const only = args.find((a) => a.startsWith('--only='))?.split('=')[1]?.split(',')

const BROWSERS = {
  edge: [
    'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe',
    'C:/Program Files/Microsoft/Edge/Application/msedge.exe',
  ],
  chrome: [
    'C:/Program Files/Google/Chrome/Application/chrome.exe',
    'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
  ],
}

function findBrowser() {
  const candidates = [...(BROWSERS[browserArg] ?? []), ...BROWSERS.chrome, ...BROWSERS.edge]
  for (const p of candidates) if (existsSync(p)) return p
  throw new Error('No Edge/Chrome executable found for puppeteer-core')
}

async function waitForServer(url, tries = 60) {
  for (let i = 0; i < tries; i += 1) {
    try {
      const r = await fetch(url)
      if (r.ok) return
    } catch {
      /* not up yet */
    }
    await new Promise((r) => setTimeout(r, 500))
  }
  throw new Error(`server did not start: ${url}`)
}

async function main() {
  const browserPath = findBrowser()
  console.log(`browser: ${browserPath}`)

  // Serve the production build unless an external URL was given.
  let server = null
  const baseUrl = explicitUrl ?? 'http://localhost:4173'
  if (!explicitUrl) {
    // Launch vite directly via node so the child is reliably killable.
    server = spawn(
      process.execPath,
      [join(appDir, 'node_modules/vite/bin/vite.js'), 'preview', '--port', '4173', '--strictPort'],
      { cwd: appDir, stdio: 'pipe' },
    )
    server.stderr?.on('data', (d) => process.stderr.write(d))
    await waitForServer(baseUrl)
    console.log(`preview server: ${baseUrl}`)
  }

  const browser = await puppeteer.launch({
    executablePath: browserPath,
    headless: true,
    protocolTimeout: 600_000,
    args: [
      '--autoplay-policy=no-user-gesture-required',
      '--enable-precise-memory-info',
      '--mute-audio',
      '--disable-renderer-backgrounding',
      '--window-size=1600,900',
      '--no-sandbox',
      `--user-data-dir=${process.env.TEMP ?? '.'}/ui004-measure-profile`,
    ],
  })

  const fixtures = only ?? ['30s', '3min', '10min']
  const reports = []
  try {
    const page = await browser.newPage()
    await page.setViewport({ width: 1600, height: 900 })
    page.on('pageerror', (e) => console.error('pageerror:', e.message))

    for (const id of fixtures) {
      console.log(`\n=== fixture ${id} ===`)
      // Fresh document per fixture so the memory baseline is honest.
      await page.goto(baseUrl, { waitUntil: 'networkidle0' })
      await page.waitForFunction('window.__ui004 !== undefined', { timeout: 20000 })
      const baseline = await page.evaluate(() => window.__ui004.readMemoryMB())

      const label = await page.evaluate(
        (fid) => window.__ui004.loadFixture(fid),
        id,
      )
      console.log(`loaded: ${label}`)

      const report = await page.evaluate(async (q) => {
        return window.__ui004.runCurrent({ quick: q })
      }, quick)
      report.fixture = label || id
      report.memory.beforeLoadMB = baseline
      reports.push(report)
      console.log(
        `  ready=${report.loadReadyMs?.toFixed(0)}ms seek p50=${report.seek?.medianMs?.toFixed(1)}ms ` +
          `loop drift=${report.loop?.periodErrMeanMs?.toFixed(2)}ms mem=${report.memory?.afterLoadMB?.toFixed(1)}MB`,
      )
    }
  } finally {
    await browser.close()
    server?.kill()
  }

  const doc = {
    tool: 'ui-004-spike',
    timestamp: new Date().toISOString(),
    browser: browserPath,
    quick,
    fixtures: reports,
  }
  mkdirSync(outDir, { recursive: true })
  const file = join(outDir, `ui-004-${Date.now()}.json`)
  writeFileSync(file, JSON.stringify(doc, null, 2))
  console.log(`\nwrote ${file}`)
  console.log(JSON.stringify(doc, null, 2))
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

import { useCallback, useEffect, useRef, useState } from 'react'
import { encodeWavPcm16Mono } from './audio/wav'
import { FIXTURE_SAMPLE_RATE, synthFixture } from './audio/synth'
import { MeasurePanel } from './components/MeasurePanel'
import { TransportBar } from './components/TransportBar'
import { WaveformView } from './components/WaveformView'
import { spikeCopy, t } from './copy'
import { readMemoryMB, runMeasurements, type FixtureReport } from './measure/harness'
import type { WaveSurferTransportAdapter } from './transport/wavesurferAdapter'
import type { TransportSnapshot } from './transport/types'

const EMPTY_SNAPSHOT: TransportSnapshot = {
  status: 'empty',
  time: 0,
  duration: 0,
  rate: 1,
  preservePitch: true,
  loop: null,
  revision: 0,
}

interface FixtureDef {
  id: string
  seconds: number
  /** Static file path under public/ (present only when generated locally). */
  url: string
}

const FIXTURES: FixtureDef[] = [
  { id: '30s', seconds: 30, url: 'fixtures/sweep_30s.wav' },
  { id: '3min', seconds: 180, url: 'fixtures/sweep_3min.wav' },
  { id: '10min', seconds: 600, url: 'fixtures/sweep_10min.wav' },
]

/** Spike instrumentation: total App renders since module load. */
let renderCount = 0

export default function App() {
  renderCount += 1
  const adapterRef = useRef<WaveSurferTransportAdapter | null>(null)
  const memoryBaselineRef = useRef<number | null>(null)
  const [, setAdapterReady] = useState(0)
  const [snapshot, setSnapshot] = useState<TransportSnapshot>(EMPTY_SNAPSHOT)
  const [fixtureId, setFixtureId] = useState('30s')
  const [fixtureLabel, setFixtureLabel] = useState('')
  const [loading, setLoading] = useState(false)
  const [hasSelection, setHasSelection] = useState(false)
  const [follow, setFollow] = useState(true)
  const [followSuspended, setFollowSuspended] = useState(false)
  const [minimapOn, setMinimapOn] = useState(false)
  const [zoomPx, setZoomPx] = useState(1)
  const [report, setReport] = useState<FixtureReport | null>(null)
  const [measuring, setMeasuring] = useState(false)
  const [measureStage, setMeasureStage] = useState('')

  const transport = useCallback(() => adapterRef.current, [])

  const onAdapter = useCallback((adapter: WaveSurferTransportAdapter) => {
    adapterRef.current = adapter
    const offSnap = adapter.subscribe(setSnapshot)
    const offZoom = adapter.getWavesurfer().on('zoom', () => {
      setZoomPx(adapter.getZoomPxPerSec())
    })
    adapter.setSelectionListener((sel) => setHasSelection(sel !== null))
    adapter.setFollow(true)
    setAdapterReady((v) => v + 1)
    // detach with the adapter lifetime
    adapter.getWavesurfer().on('destroy', () => {
      offSnap()
      offZoom()
    })
  }, [])

  const loadFixture = useCallback(async (def: FixtureDef): Promise<string> => {
    const adapter = adapterRef.current
    if (!adapter) return ''
    setLoading(true)
    memoryBaselineRef.current = readMemoryMB()
    adapter.clearSelection()
    try {
      // Prefer a real file (same bytes the product cache would serve);
      // fall back to in-browser synthesis when the file was not generated.
      const head = await fetch(def.url, { method: 'HEAD' }).catch(() => null)
      if (head && head.ok) {
        await adapter.load({ kind: 'url', url: def.url })
        return `${def.id} (file)`
      }
      const pcm = synthFixture(def.seconds, FIXTURE_SAMPLE_RATE)
      const blob = encodeWavPcm16Mono(pcm, FIXTURE_SAMPLE_RATE)
      await adapter.load({ kind: 'blob', blob })
      return `${def.id} (synth)`
    } finally {
      setLoading(false)
    }
  }, [])

  const onLoadClick = useCallback(() => {
    const def = FIXTURES.find((f) => f.id === fixtureId)
    if (!def) return
    void loadFixture(def).then(setFixtureLabel)
  }, [fixtureId, loadFixture])

  const runMeasure = useCallback(async () => {
    const adapter = adapterRef.current
    if (!adapter || adapter.getSnapshot().status === 'empty') return
    setMeasuring(true)
    try {
      const r = await runMeasurements({
        adapter,
        fixtureLabel: fixtureLabel || fixtureId,
        memoryBaselineMB: memoryBaselineRef.current,
        onProgress: setMeasureStage,
      })
      setReport(r)
    } finally {
      setMeasuring(false)
      setMeasureStage('')
    }
  }, [fixtureId, fixtureLabel])

  const onToggleLoop = useCallback(() => {
    const adapter = adapterRef.current
    if (!adapter) return
    if (adapter.getSnapshot().loop) adapter.setLoop(null)
    else {
      const sel = adapter.getSelection()
      if (sel) adapter.setLoop(sel)
    }
  }, [])

  const onToggleFollow = useCallback(() => {
    setFollow((prev) => {
      const next = !prev || followSuspended // resume counts as on
      adapterRef.current?.setFollow(next)
      if (next) setFollowSuspended(false)
      return next
    })
  }, [followSuspended])

  const onUserPanDuringPlayback = useCallback(() => {
    setFollowSuspended((s) => {
      if (!s && follow) adapterRef.current?.setFollow(false)
      return follow ? true : s
    })
  }, [follow])

  const onResumeFollow = useCallback(() => {
    setFollowSuspended(false)
    setFollow(true)
    adapterRef.current?.setFollow(true)
  }, [])

  const onZoom = useCallback((px: number) => {
    adapterRef.current?.zoom(px)
    setZoomPx(adapterRef.current?.getZoomPxPerSec() ?? px)
  }, [])

  // Keyboard transport (deck tooltips: Space/K/J/L, Home/End, Ctrl+L).
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      const el = e.target as HTMLElement
      if (el && (el.tagName === 'INPUT' || el.tagName === 'SELECT' || el.tagName === 'TEXTAREA'))
        return
      const c = adapterRef.current
      if (!c || c.getSnapshot().status === 'empty' || c.getSnapshot().status === 'loading') return
      switch (e.code) {
        case 'Space':
          e.preventDefault()
          if (e.shiftKey) c.stop()
          else if (c.getSnapshot().status === 'playing') c.pause()
          else void c.play()
          break
        case 'KeyK':
          if (c.getSnapshot().status === 'playing') c.pause()
          else void c.play()
          break
        case 'KeyJ':
          void c.seek(c.getCurrentTime() - 5)
          break
        case 'KeyL':
          if (e.ctrlKey || e.metaKey) {
            e.preventDefault()
            onToggleLoop()
          } else {
            void c.seek(c.getCurrentTime() + 5)
          }
          break
        case 'Home':
          e.preventDefault()
          void c.seek(0)
          break
        case 'End':
          e.preventDefault()
          void c.seek(c.getDuration())
          break
        case 'Delete':
        case 'Backspace':
          c.clearSelection()
          break
        default:
          break
      }
    }
    window.addEventListener('keydown', onKey)
    return () => window.removeEventListener('keydown', onKey)
  }, [onToggleLoop])

  // Puppeteer/measurement bridge.
  useEffect(() => {
    const api = {
      loadFixture: (id: string) => {
        const def = FIXTURES.find((f) => f.id === id)
        return def ? loadFixture(def) : Promise.resolve('')
      },
      runCurrent: (opts?: { quick?: boolean }) => {
        const adapter = adapterRef.current
        if (!adapter) return Promise.resolve(null)
        return runMeasurements({
          adapter,
          fixtureLabel: fixtureLabel || fixtureId,
          memoryBaselineMB: memoryBaselineRef.current,
          quick: opts?.quick,
        })
      },
      adapter: () => adapterRef.current,
      readMemoryMB,
      getRenderCount: () => renderCount,
      fixtures: FIXTURES.map((f) => f.id),
    }
    ;(window as unknown as { __ui004?: unknown }).__ui004 = api
  }, [fixtureId, fixtureLabel, loadFixture])

  return (
    <div className="app">
      <header className="app-header">
        <h1>{spikeCopy.title}</h1>
        <div className="fixture-bar">
          <label>
            {spikeCopy.fixtureLabel}
            <select value={fixtureId} onChange={(e) => setFixtureId(e.target.value)}>
              {FIXTURES.map((f) => (
                <option key={f.id} value={f.id}>
                  {f.id === '30s'
                    ? spikeCopy.fixture30s
                    : f.id === '3min'
                      ? spikeCopy.fixture3min
                      : spikeCopy.fixture10min}
                </option>
              ))}
            </select>
          </label>
          <button type="button" onClick={onLoadClick} disabled={loading}>
            {loading ? spikeCopy.generating : spikeCopy.loadFixture}
          </button>
          {fixtureLabel && <span className="loaded-label">{fixtureLabel}</span>}
          {!fixtureLabel && <span className="hint">{spikeCopy.noFixtureLoaded}</span>}
        </div>
      </header>

      <TransportBar
        snapshot={snapshot}
        transport={transport}
        onToggleLoop={onToggleLoop}
        onClearRegion={() => adapterRef.current?.clearSelection()}
        onPlaySelection={() => void adapterRef.current?.playSelection()}
        follow={follow}
        followSuspended={followSuspended}
        onToggleFollow={onToggleFollow}
        onResumeFollow={onResumeFollow}
        minimapOn={minimapOn}
        onToggleMinimap={() => setMinimapOn((v) => !v)}
        zoomPx={zoomPx}
        onZoom={onZoom}
        hasSelection={hasSelection}
      />

      <WaveformView
        onAdapter={onAdapter}
        showMinimap={minimapOn}
        onUserPanDuringPlayback={onUserPanDuringPlayback}
      />
      <p className="hint region-hint">{spikeCopy.regionHandles}</p>
      {followSuspended && follow && (
        <p className="follow-note" role="status">
          {t('transport.followPaused')}
        </p>
      )}

      <MeasurePanel
        ready={snapshot.status !== 'empty' && snapshot.status !== 'loading'}
        running={measuring}
        stage={measureStage}
        report={report}
        onRun={runMeasure}
      />

      <footer className="app-footer">
        <span>{t('app.privacyNote')}</span>
      </footer>
    </div>
  )
}

/**
 * Deterministic PCM synthesis for UI-004 fixtures — TypeScript port of
 * scripts/generate_audio_fixtures.py (same formula, same LCG noise).
 *
 * Used to synthesize the 3 min / 10 min fixtures on demand inside the app so
 * no large WAV binaries are committed. Yields Float32 samples in [-1, 1].
 */

export const FIXTURE_SAMPLE_RATE = 44100
const NOTE_SECONDS = 2.0
const SCALE_HZ = [220.0, 246.94, 261.63, 293.66, 329.63, 392.0, 440.0, 523.25]
const ATTACK_S = 0.03
const DECAY = 5.0
const TICK_PERIOD_S = 10.0
const TICK_LEN_S = 0.06
const TICK_HZ = 1000.0
const NOISE_AMP = 0.015
const MASTER_AMP = 0.5

function lcg(seed: number): number {
  // uint32 arithmetic matching the Python `mod 2**32` implementation
  return (Math.imul(1103515245, seed) + 12345) >>> 0
}

/** Synthesize `seconds` of the fixture signal into a Float32Array. */
export function synthFixture(seconds: number, sampleRate = FIXTURE_SAMPLE_RATE): Float32Array {
  const total = Math.floor(seconds * sampleRate)
  const out = new Float32Array(total)
  let seed = 0x1234abcd
  const twoPi = 2 * Math.PI
  for (let i = 0; i < total; i += 1) {
    const t = i / sampleRate
    const noteIdx = Math.floor(t / NOTE_SECONDS)
    const u = (t - noteIdx * NOTE_SECONDS) / NOTE_SECONDS

    let sample = 0
    if (noteIdx % 8 !== 7) {
      const octave = Math.floor(noteIdx / 8) % 2 === 0 ? 1 : 0.5
      const freq = SCALE_HZ[noteIdx % SCALE_HZ.length] * octave
      const phase = twoPi * freq * t + 0.3 * Math.sin(twoPi * 5 * t)
      const envAttack = Math.min(1, (u * NOTE_SECONDS) / ATTACK_S)
      const env = envAttack * Math.exp(-DECAY * u)
      sample += (Math.sin(phase) + 0.3 * Math.sin(2 * phase)) * env
    }

    const tickPos = t % TICK_PERIOD_S
    if (tickPos < TICK_LEN_S) {
      const tickEnv = Math.sin((Math.PI * tickPos) / TICK_LEN_S)
      sample += 0.6 * Math.sin(twoPi * TICK_HZ * t) * tickEnv
    }

    seed = lcg(seed)
    const noise = (seed / (1 << 31) - 1) * NOISE_AMP
    out[i] = Math.max(-1, Math.min(1, (sample + noise) * MASTER_AMP))
  }
  return out
}

/** Minimal PCM16 mono WAV encoder (RIFF), matching the Python fixtures. */

export function encodeWavPcm16Mono(samples: Float32Array, sampleRate: number): Blob {
  const dataBytes = samples.length * 2
  const buffer = new ArrayBuffer(44 + dataBytes)
  const view = new DataView(buffer)

  const writeStr = (offset: number, s: string) => {
    for (let i = 0; i < s.length; i += 1) view.setUint8(offset + i, s.charCodeAt(i))
  }

  writeStr(0, 'RIFF')
  view.setUint32(4, 36 + dataBytes, true)
  writeStr(8, 'WAVE')
  writeStr(12, 'fmt ')
  view.setUint32(16, 16, true) // fmt chunk size
  view.setUint16(20, 1, true) // PCM
  view.setUint16(22, 1, true) // mono
  view.setUint32(24, sampleRate, true)
  view.setUint32(28, sampleRate * 2, true) // byte rate
  view.setUint16(32, 2, true) // block align
  view.setUint16(34, 16, true) // bit depth
  writeStr(36, 'data')
  view.setUint32(40, dataBytes, true)

  let offset = 44
  for (let i = 0; i < samples.length; i += 1) {
    const s = Math.max(-1, Math.min(1, samples[i]))
    view.setInt16(offset, Math.round(s * 32767), true)
    offset += 2
  }
  return new Blob([buffer], { type: 'audio/wav' })
}

import { useEffect, useRef } from 'react'
import { t } from '../copy'
import type { TransportController } from '../transport/types'

export function formatClock(seconds: number): string {
  if (!Number.isFinite(seconds) || seconds < 0) seconds = 0
  const m = Math.floor(seconds / 60)
  const s = Math.floor(seconds % 60)
  const ms = Math.floor((seconds % 1) * 1000)
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}.${String(ms).padStart(3, '0')}`
}

/**
 * Playhead time readout. Updates a DOM text node via rAF reading the
 * controller's audio clock directly — deliberately NOT React state, so the
 * app never re-renders at frame rate (GUI_UX_PLAN §10 TransportState rule).
 */
export function TimeReadout({ transport }: { transport: () => TransportController | null }) {
  const ref = useRef<HTMLSpanElement>(null)
  const transportRef = useRef(transport)
  transportRef.current = transport

  useEffect(() => {
    let raf = 0
    let last = ''
    const tick = () => {
      const c = transportRef.current()
      const text = c
        ? `${formatClock(c.getCurrentTime())} / ${formatClock(c.getDuration())}`
        : '--:--.--- / --:--.---'
      if (text !== last && ref.current) {
        ref.current.textContent = text
        last = text
      }
      raf = requestAnimationFrame(tick)
    }
    raf = requestAnimationFrame(tick)
    return () => cancelAnimationFrame(raf)
  }, [])

  return (
    <span
      ref={ref}
      className="time-readout"
      role="status"
      aria-label={t('transport.timeDisplayAria')}
    />
  )
}

import { spikeCopy, t } from '../copy'
import { SUPPORTED_RATES, type TransportController, type TransportSnapshot } from '../transport/types'
